"""Combination helpers."""


def pairs(items):
    """Every pair of distinct positions as (items[i], items[j]) with i < j, in order."""
    out = []
    for i in range(len(items)):
        for j in range(len(items)):
            if i != j:
                out.append((items[i], items[j]))
    return out

