from pairs import pairs

def test_ordered_pairs():
    assert pairs([1, 2, 3]) == [(1, 2), (1, 3), (2, 3)]
    assert pairs(['a', 'b', 'c', 'd']) == [
        ('a', 'b'), ('a', 'c'), ('a', 'd'), ('b', 'c'), ('b', 'd'), ('c', 'd'),
    ]
def test_duplicate_values_kept():
    assert pairs(['a', 'a']) == [('a', 'a')]
    assert pairs([1, 1, 1]) == [(1, 1), (1, 1), (1, 1)]
def test_small():
    assert pairs([1]) == []
    assert pairs([]) == []

